#include "assault76_internal.h"
/* $064550..$065F40. Source names Hostage/Patrol are not actor identities. */
static void tick(struct EntityPool*,struct NativeEntity*,void*);
void r76_schedule(struct NativeEntity*e,unsigned s){e->tick=tick;enemy_schedule(&e->payload.enemy,s);}
static void init(struct NativeEntity*e,unsigned s){uint8_t*b=(uint8_t*)&e->payload.enemy.assault76;for(unsigned i=0;i<sizeof(e->payload.enemy.assault76);i++)b[i]=255;e->payload.enemy.selector=65535;r76_schedule(e,s);}
struct NativeEntity*r76_allocate(struct WeaponWorld*w,struct EntityRef parent,enum EntityInsert order,const struct PlayerTransform*t,unsigned s){struct NativeEntity*n=enemy_allocate(w,parent,order,t,tick);if(n)init(n,s);return n;}
struct NativeEntity*r76_child(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){return r76_allocate(w,entity_ref(e),ENTITY_FIRST_CHILD,&e->payload.enemy.actor.transform,s);}
void r76_entry(struct EnemyActor*q,uint16_t n){if(n!=65535){animation_begin(&q->actor.animation,n);q->actor.movement_flags|=32;}}
void r76_start(struct EnemyActor*q,unsigned n){r76_entry(q,assault76_entries[n]);}
void r76_defense(struct EnemyActor*q,unsigned n){q->actor.defense=n==65535?0:assault76_bindings[n].defense;q->actor.defense_count=n==65535?0:assault76_bindings[n].count;}
void r76_attack(struct EnemyActor*q,unsigned n){if(n==65535)q->actor.attack=0;else{q->attack_set=(struct HitAttackSet){assault76_bindings[n].attack,assault76_bindings[n].count};q->actor.attack=&q->attack_set;}}
int16_t r76_rank(struct WeaponWorld*w,struct EnemyActor*q,unsigned n){struct InteractionWorld*r=w->interactions;if(!r||!r->rank_valid||n>=R76R_COUNT){enemy_fault(w);return 0;}unsigned i=(interaction_rank(w,&q->actor,runtime_owner_assault76[n]))*8+(q->source_flags&3)*2;const struct Assault76RankData*t=&assault76_rank[n];if(t->choices)i=t->choices[i+((uint8_t)(r->player_count_flag-1)&1)]*8+((tk_random(w)&14)>>1);else i+=(r->player_count_flag&2)>>1;return (int16_t)t->values[i];}
struct Context {struct WeaponWorld*w;struct NativeEntity*e;};
static uint32_t read(void*ctx,unsigned f,unsigned width){(void)width;struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;switch(f){case R76F_20_1:return q->actor.phase;case R76F_5C_4:return q->assault76.delays;case R76F_88_2:return (uint16_t)q->assault76.angle;case R76F_3B_1:return q->actor.animation.pose;case R76F_74_2:return (uint16_t)q->assault76.count;case R76F_34_2:return q->selector;default:enemy_fault(c->w);return 0;}}
static int field(void*ctx,unsigned f,unsigned width,enum AnimationFieldOperation op,uint32_t v){struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;uint32_t old=read(ctx,f,width);if(op==AN_FIELD_AND)v&=old;else if(op==AN_FIELD_OR)v|=old;else if(op==AN_FIELD_XOR)v^=old;else if(op!=AN_FIELD_SET)return enemy_fault(c->w);switch(f){case R76F_20_1:q->actor.phase=v;break;case R76F_5C_4:if(v)return enemy_fault(c->w);q->assault76.delays=0;break;case R76F_88_2:q->assault76.angle=v;break;case R76F_3B_1:q->actor.animation.pose=v;break;case R76F_74_2:q->assault76.count=v;break;case R76F_34_2:q->selector=v;break;default:return enemy_fault(c->w);}return !c->w->fault;}
static int delay(void*ctx,unsigned f,unsigned i,uint8_t*out){struct Context*c=ctx;if(f!=R76F_5C_4||c->e->payload.enemy.assault76.delays||i>=48)return enemy_fault(c->w);*out=assault76_delays[i];return 1;}
static int bind(void*ctx,unsigned k,uint32_t v){struct Context*c=ctx;unsigned n=v==0xffffffffu?65535:v;if(n!=65535&&n>=10)return enemy_fault(c->w);if(k==AN_DEFENSE)r76_defense(&c->e->payload.enemy,n);else if(k==AN_ATTACK)r76_attack(&c->e->payload.enemy,n);else return enemy_fault(c->w);return 1;}
static int sound(void*ctx,uint16_t n,int stop){struct Context*c=ctx;return c->w->sound&&c->w->sound(c->w->scene,n,stop)?1:enemy_fault(c->w);}
static int call(void*ctx,unsigned n,struct Animation*an){(void)an;struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;struct WeaponActor*a=&q->actor;
 switch(n){case R76C_65EE8:return r76_emit(c->w,c->e,0);case R76C_65EF4:return r76_emit(c->w,c->e,1);case R76C_65F00:return r76_emit(c->w,c->e,2);case R76C_65F0C:return r76_emit(c->w,c->e,3);case R76C_65F18:return r76_emit(c->w,c->e,4);case R76C_65DDC:return r76_emit(c->w,c->e,5);case R76C_65E30:return r76_emit(c->w,c->e,6);case R76C_65D94:a->ax=q->assault76.speed>>5;return a->ax?1:enemy_fault(c->w);case R76C_283CA:hit_begin_attack(&a->hit);break;case R76C_4A0D4:if(!c->w->enemies)return enemy_fault(c->w);a->palette=c->w->enemies->blood_enabled?14:47;break;case R76C_4A1BA:return tk_sound(c->w,(uint16_t)q->assault76.count);case R76C_29C956:a->palette=40;break;default:return enemy_fault(c->w);}return 1;}
int r76_animate(struct WeaponWorld*w,struct NativeEntity*e){struct WeaponActor*a=&e->payload.enemy.actor;if(a->animation.cursor==65535)return 0;struct Context c={w,e};struct AnimationOwner o={.context=&c,.read=read,.write=field,.bind=bind,.sound=sound,.call=call,.delay=delay};int done=animation_step(&a->animation,&assault76_program,&o);if(a->animation.fault)enemy_fault(w);return done;}
int r76_follow(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*p=tk_parent(w,e);if(!p)return 0;struct PlayerTransform*t=&e->payload.enemy.actor.transform;uint8_t group=t->display_group;*t=p->actor.transform;t->display_group=group;return 1;}
int r76_parent_done(struct WeaponWorld*w,struct NativeEntity*e){struct NativeEntity*p=entity_get(w->entities,e->parent);return !p||p->deleting;}
int r76_outside(struct WeaponWorld*w,struct WeaponActor*a,int custom){static const int16_t b[]={0,1,0,1};return interaction_outside(w,a,custom?assault76_bounds:b,1);}
static int count(struct WeaponWorld*w,struct EnemyActor*q,int increment){if(!w->enemies){enemy_fault(w);return 0;}unsigned v=q->assault76.variant!=0;if(increment)return ++w->enemies->assault76.current[v];int8_t a=w->enemies->assault76.previous[v],b=w->enemies->assault76.current[v];return b>a?b:a;}
static void clamp_speed(struct EnemyActor*q){int16_t n=q->assault76.speed;if(q->actor.transform.facing&1?n<=q->actor.vx:n>=q->actor.vx){q->actor.vx=n;q->actor.ax=0;}}
static int tail(struct WeaponWorld*w,struct NativeEntity*e,int foot){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;if(foot){int r=terrain_weapon_foot_contact(w->interactions->terrain,a);if(r<0)return enemy_fault(w);if(!r)r76_schedule(e,R76_DEAD);}q->dead=0;count(w,q,1);if(!tk_hit_sound(w,a))return 0;if(a->hit.flags&1)r76_schedule(e,R76_DEAD);a->hit.flags&=247;if(r76_outside(w,a,1))r76_schedule(e,R76_DELETE);return !w->fault;}
static int enter(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;struct NativeEntity*n;unsigned v=q->assault76.variant;
 switch(a->state){
 case R76_ROOT:if(q->assault76.form&1)a->transform.facing|=1;a->palette=v?0x146:0x44;if(!tk_settle(w,a))return 0;a->hit.hp=r76_rank(w,q,v?R76R_HP_B:R76R_HP_A);interaction_priority(w,a,v?0x8000:0x4000,20);q->dead=0;if(q->assault76.form>=6){if(!r76_child(w,e,R76_OVERLAY))return 0;a->state=R76_RUN_WAIT;break;}q->assault76.limit=(q->params[2]&31)*16;q->assault76.serial=(uint16_t)q->params[1]<<8;q->assault76.drive=0;a->state=R76_WAIT;break;
 case R76_WALK:if(q->assault76.rider&&!r76_child(w,e,R76_PILOT))return 0;r76_defense(q,v?R76B_BODY_B:R76B_BODY_A);if(v){r76_schedule(e,R76_CHARGE);return 2;}q->assault76.drive=1;a->vx=q->assault76.speed=tk_word(-tk_faced(a,r76_rank(w,q,R76R_SPEED_A)));r76_start(q,R76A_WALK_A);break;
 case R76_STOP:if(!tk_sound(w,0x1060))return 0;q->assault76.drive=0;a->ax=tk_word(-(a->vx>>5));r76_start(q,v?R76A_STOP_B:R76A_STOP_A);break;
 case R76_KNEEL:q->assault76.drive=0;m4_reset(a);if(v){q->assault76.timer=r76_rank(w,q,R76R_WAIT_B);r76_start(q,R76A_WAIT_B);a->state=R76_WAIT_B;}else{q->assault76.timer=10;r76_start(q,R76A_WAIT_A);a->state=R76_WAIT_A;}break;
 case R76_STAND:if(!tk_sound(w,0x105e))return 0;q->assault76.drive=0;r76_start(q,v?R76A_STAND_B:R76A_STAND_A);break;
 case R76_CHARGE:if(!r76_child(w,e,R76_TRAIL))return 0;q->assault76.speed=tk_word(-tk_faced(a,r76_rank(w,q,R76R_SPEED_B)));r76_attack(q,R76B_CHARGE);q->assault76.drive=1;r76_start(q,v?R76A_CHARGE_B:R76A_CHARGE_A);break;
 case R76_DEAD:case R76_MUSIC:case R76_WRECK:if(!tk_sound(w,a->state==R76_DEAD?0x1021:0x1023))return 0;q->assault76.drive=0;a->display_flags&=253;r76_start(q,a->state==R76_WRECK?R76A_WRECK:R76A_DEAD);break;
 case R76_RUN:r76_defense(q,R76B_BODY_B);if(!tk_sound(w,0x105e))return 0;q->assault76.limit=(q->params[2]&31)*16;a->vx=q->assault76.speed=tk_word(-tk_faced(a,r76_rank(w,q,R76R_SPEED_A)));r76_start(q,R76A_RUN);break;
 case R76_LEAP:r76_attack(q,R76B_LEAP);r76_start(q,R76A_LEAP);break;
 case R76_THROWN:if(!tk_sound(w,0x105c))return 0;n=r76_child(w,e,R76_ESCAPE);if(!n)return 0;transform_integer_offset(&n->payload.enemy.actor.transform,tk_faced(a,24),8);n->payload.enemy.actor.vx=a->vx>>1;a->vy=0xaa7;a->ay=-303;a->vx>>=2;transform_integer_offset(&a->transform,0,32);a->transform.priority=0xd000;r76_start(q,R76A_THROWN);break;
 case R76_SURFACE:m4_screen(w,a,tk_sx(w,a),288);interaction_priority(w,a,0xf000,28);return boss_fx_transform(w,e,BFX_SURFACE20),0;
 case R76_MANAGER:a->display_flags&=253;if(!w->enemies)return enemy_fault(w);w->enemies->assault76.stop[0]=w->enemies->assault76.stop[1]=0;break;
 case R76_STOP_ALL:if(!w->enemies)return enemy_fault(w);w->enemies->assault76.stop[0]=0x34;w->enemies->assault76.stop[1]=0x35;entity_delete_children(w->entities,e);entity_delete(w->entities,e);return 0;
 default:return enemy_fault(w);
 }return !w->fault;
}
static int frame(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;int done,r;
 if(s==R76_MANAGER){if(!w->enemies)return enemy_fault(w);for(unsigned i=0;i<2;i++){w->enemies->assault76.previous[i]=w->enemies->assault76.current[i];w->enemies->assault76.current[i]=0;}return 1;}
 if(s==R76_WAIT||s==R76_RUN_WAIT){if(!q->params[0])r76_schedule(e,s==R76_WAIT?R76_WALK:R76_RUN);if(count(w,q,0)<(int8_t)q->params[0]){r76_schedule(e,s==R76_WAIT?R76_WALK:R76_RUN);count(w,q,1);if(s==R76_WAIT&&!tk_sound(w,0x105d))return 0;}if(!w->enemies)return enemy_fault(w);if((s==R76_WAIT&&w->enemies->assault76.stop[0]==0x34)||w->enemies->assault76.stop[1]==0x35)r76_schedule(e,R76_DELETE);return !w->fault;}
 if(s==R76_DEAD||s==R76_MUSIC||s==R76_WRECK){if(interaction_move(w,a,WMOVE_SYNC)<0)return 0;if(r76_animate(w,e)||r76_outside(w,a,1))r76_schedule(e,R76_DELETE);return !w->fault;}
 if(s==R76_THROWN){r=interaction_move(w,a,WMOVE_FALL);if(r<0)return 0;if(r)r76_schedule(e,R76_SURFACE);r76_animate(w,e);if(tk_sy(w,a)<=288)r76_schedule(e,R76_SURFACE);hit_begin_attack(&a->hit);if(!enemy_attack(w,a))return 0;if(a->hit.flags&2)r76_schedule(e,R76_WRECK);a->hit.flags&=247;if(!tk_hit_sound(w,a))return 0;if(a->hit.flags&1)r76_schedule(e,R76_WRECK);if(r76_outside(w,a,1))r76_schedule(e,R76_DELETE);return !w->fault;}
 r=interaction_move(w,a,s==R76_LEAP?WMOVE_POINT:s==R76_WAIT_A||s==R76_WAIT_B?WMOVE_SYNC:WMOVE_FLAT);if(r<0)return 0;
 switch(s){
 case R76_WALK:if(r)r76_schedule(e,R76_STOP);r76_animate(w,e);if(a->transform.facing&1?q->assault76.limit<=tk_sx(w,a):q->assault76.limit>=tk_sx(w,a))r76_schedule(e,R76_STOP);q->assault76.serial=tk_word(q->assault76.serial-1);if(q->assault76.serial<=0)r76_schedule(e,R76_STOP);break;
 case R76_STOP:if(!a->vx)a->ax=0;if(!(w->frame_phase&7)){struct NativeEntity*n=r76_child(w,e,R76_DUST);if(!n)return 0;transform_integer_offset(&n->payload.enemy.actor.transform,tk_faced(a,24),0);n->payload.enemy.actor.vx=a->ax;n->payload.enemy.actor.transform.priority++;}done=r76_animate(w,e);if(done&&!a->vx)r76_schedule(e,R76_KNEEL);break;
 case R76_WAIT_A:if(q->assault76.timer>0){q->assault76.timer=tk_word(q->assault76.timer-1);if(q->assault76.timer<=0)a->phase=8;}r76_animate(w,e);if(q->dead==4)r76_schedule(e,R76_STAND);if(tk_sx(w,a)<=0)r76_schedule(e,R76_DELETE);break;
 case R76_WAIT_B:r76_animate(w,e);q->assault76.timer=tk_word(q->assault76.timer-1);if(q->assault76.timer<=0)r76_schedule(e,R76_STAND);break;
 case R76_STAND:if(r76_animate(w,e))r76_schedule(e,R76_CHARGE);break;
 case R76_CHARGE:if(r)r76_schedule(e,R76_DEAD);clamp_speed(q);r76_animate(w,e);hit_begin_attack(&a->hit);if(!enemy_attack(w,a))return 0;if(a->hit.flags&2)r76_schedule(e,R76_DEAD);break;
 case R76_RUN:if(r)r76_schedule(e,R76_LEAP);clamp_speed(q);r76_animate(w,e);if(a->transform.facing&1?tk_sx(w,a)>=q->assault76.limit:tk_sx(w,a)<=q->assault76.limit)r76_schedule(e,R76_LEAP);break;
 case R76_LEAP:clamp_speed(q);if(r76_animate(w,e))r76_schedule(e,R76_THROWN);break;
 default:return enemy_fault(w);
 }
 if(s==R76_RUN||s==R76_LEAP){hit_begin_attack(&a->hit);if(!enemy_attack(w,a))return 0;if(a->hit.flags&2)r76_schedule(e,R76_MUSIC);return tail(w,e,0);}return tail(w,e,1);
}
static void tick(struct EntityPool*p,struct NativeEntity*e,void*world){struct WeaponWorld*w=world;if(w->fault)return;struct EnemyActor*q=&e->payload.enemy;for(unsigned b=0;b<12;b++){unsigned s=q->actor.state;if(s==R76_DELETE||s==R76_DELETE_TREE){r76_defense(q,65535);if(s==R76_DELETE_TREE)entity_delete_children(p,e);entity_delete(p,e);return;}if(q->entry){q->entry=0;int r=s<R76_PILOT?enter(w,e):s<R76_GRENADE?r76_parts_enter(w,e):r76_ordnance_enter(w,e);if(!r||w->fault)return;if(r==2)continue;}if(!e->active||e->deleting)return;s=q->actor.state;int r=s<R76_PILOT?frame(w,e,s):s<R76_GRENADE?r76_parts_frame(w,e,s):r76_ordnance_frame(w,e,s);if(r==2)continue;return;}enemy_fault(w);}
int assault76_spawn(struct WeaponWorld*w,struct EntityRef parent,enum EntityInsert order,uint16_t id,const struct PlayerTransform*t,const uint8_t params[8]){if(id<76||id>85)return enemy_fault(w);struct NativeEntity*e=enemy_allocate(w,parent,order,t,tick);if(!e)return 0;init(e,id==84?R76_MANAGER:id==85?R76_STOP_ALL:R76_ROOT);struct EnemyActor*q=&e->payload.enemy;q->assault76.form=id-76;q->assault76.variant=id>=78;q->assault76.rider=id<=77||id==80||id==81;/* even templates OR facing bit; odd templates preserve it */q->assault76.form^=1;if(params)for(unsigned i=0;i<8;i++)q->params[i]=params[i];return 1;}
